fn solve(queries: Vec<(i8, i8)>) -> Vec<i8> {
    // Define the prefix sum function S(k) according to spec:
    // S(k) = 0 if k <= 0
    // S(k) = k/2 if k even (>0)
    // S(k) = -((k+1)/2) if k odd (>0)
    fn prefix_sum(k: i8) -> i8 {
        if k <= 0 {
            0
        } else if k % 2 == 0 {
            k / 2
        } else {
            -((k + 1) / 2)
        }
    }

    let mut result = Vec::with_capacity(queries.len());
    for &(l, r) in &queries {
        // l and r satisfy 1 <= l <= r per precondition
        let val = prefix_sum(r) - prefix_sum(l - 1);
        result.push(val);
    }

    result
}